CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT, full_name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'USER', created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_users_email(email));
CREATE TABLE accommodations (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(150) NOT NULL, type VARCHAR(30) NOT NULL, city VARCHAR(100) NOT NULL, country VARCHAR(100) NOT NULL, address VARCHAR(255) NOT NULL, short_description VARCHAR(255) NOT NULL, description TEXT NOT NULL, price_per_night DECIMAL(10,2) NOT NULL, max_guests INT NOT NULL, rating DECIMAL(2,1) NOT NULL DEFAULT 0.0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(id));
CREATE TABLE accommodation_images (id BIGINT NOT NULL AUTO_INCREMENT, accommodation_id BIGINT NOT NULL, url VARCHAR(500) NOT NULL, sort_order INT NOT NULL DEFAULT 0, PRIMARY KEY(id), FOREIGN KEY(accommodation_id) REFERENCES accommodations(id) ON DELETE CASCADE);
CREATE TABLE amenities (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(60) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_amenity_name(name));
CREATE TABLE accommodation_amenities (accommodation_id BIGINT NOT NULL, amenity_id BIGINT NOT NULL, PRIMARY KEY(accommodation_id, amenity_id), FOREIGN KEY(accommodation_id) REFERENCES accommodations(id) ON DELETE CASCADE, FOREIGN KEY(amenity_id) REFERENCES amenities(id) ON DELETE CASCADE);
CREATE TABLE bookings (id BIGINT NOT NULL AUTO_INCREMENT, reference VARCHAR(20) NOT NULL, user_id BIGINT NOT NULL, accommodation_id BIGINT NOT NULL, check_in DATE NOT NULL, check_out DATE NOT NULL, guests INT NOT NULL, nights INT NOT NULL, price_per_night DECIMAL(10,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_booking_reference(reference), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(accommodation_id) REFERENCES accommodations(id));
CREATE TABLE contact_messages (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, subject VARCHAR(150) NOT NULL, message TEXT NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(id));

